# Ripristina il file gradio_app.py COMPLETO per Render.
# Non modifica hf_engine.py, i sei moduli o i contenuti di Gradio.
from pathlib import Path
import base64
import ast
import hashlib

root = Path('/content/agentic-financial-intelligence')
if not root.is_dir():
    root = Path.cwd()
target = root / 'gradio_app.py'
original_bytes = base64.b64decode(
''
)
source = original_bytes.decode('utf-8')
ast.parse(source, filename=str(target))
assert source.startswith('"""Gradio landing page for Agentic Financial Intelligence."""'), 'Intestazione inattesa'
assert 'from hf_engine import initialize_engine' in source
assert 'from hf_engine import ask' in source
assert 'import spaces' not in source and '@spaces.GPU' not in source
assert 'server_port=int(os.environ.get("PORT", "7860"))' in source
target.write_bytes(original_bytes)
assert target.read_bytes() == original_bytes
print('FILE RIPRISTINATO:', target)
print('Sintassi Python: OK')
print('SHA256:', hashlib.sha256(original_bytes).hexdigest())
print('Prime 3 righe:', source.splitlines()[:3])
print('Ora puoi rieseguire il modulo 6 del notebook diagnostico. Prima riavvia il processo precedente, se attivo.')
